package main

import (
	"hash/fnv"
	"strings"
)

const evalRubricVersion = 1

const evalCrossCheckSampleRate = 0.1

var evalSelfIDPatterns = []string{
	"generated by",
	"written by claude",
	"as an ai language model",
	"anthropic",
	"claude-opus",
	"claude-sonnet",
	"claude-haiku",
	"openai",
	"gpt-4",
	"gpt-3",
	"chatgpt",
	"gemini",
	"copilot",
}

func evalScrubSelfID(diff string) []string {
	matches := []string{}
	for _, line := range strings.Split(diff, "\n") {
		if !strings.HasPrefix(line, "+") || strings.HasPrefix(line, "+++") {
			continue
		}
		lower := strings.ToLower(line)
		for _, pat := range evalSelfIDPatterns {
			if strings.Contains(lower, pat) {
				matches = append(matches, strings.TrimSpace(strings.TrimPrefix(line, "+")))
				break
			}
		}
	}
	return matches
}

func evalDiffTouchesTestFile(diff string) bool {
	inTestFile := false
	addedFile := false
	flagged := func() bool { return inTestFile && !addedFile }
	for _, line := range strings.Split(diff, "\n") {
		if strings.HasPrefix(line, "diff --git") {
			if flagged() {
				return true
			}
			inTestFile = strings.Contains(line, "_test.go")
			addedFile = false
			continue
		}
		if inTestFile && strings.HasPrefix(line, "new file mode") {
			addedFile = true
		}
	}
	return flagged()
}

func evalShouldCrossCheckSample(beadID string) bool {
	h := fnv.New32a()
	_, _ = h.Write([]byte(beadID))
	bucket := float64(h.Sum32()%1000) / 1000.0
	return bucket < evalCrossCheckSampleRate
}
